ActualBridgeReference :=
    DIRECT_ACTUAL_BRIDGE {
      bridge_target: Occurrence | Process
      actuality_evaluation: ActualDynamicEvaluationBinding
    }
  | RESOLVED_DYNAMIC_BRIDGE {
      bridge_target: Occurrence | Process
      dynamics_evaluation: ActualDynamicEvaluationBinding
    }

BridgeHistoryBasis :=
    ACTUAL_BRIDGE_BASIS {
      ordered_actual_bridge_references:
          nonempty [ActualBridgeReference]
      bridge_evidence_references: [Claim | Record] | NONE | OPEN
      state_and_configuration_mappings
      causal_or_derivation_claims: [Claim | Record] | NONE | OPEN
      provenance_references: [Claim | Record] | NONE | OPEN
      coverage: CoveragePosture
    }
  | OBSERVATIONAL_GAP_BASIS {
      known_boundary_references
      unresolved_interval_or_segments
      possible_bridge_families: [Term] | NONE | OPEN
      excluded_bridge_families: [Term] | NONE | OPEN
      coverage: CoveragePosture
    }
  | NO_BRIDGE_CLAIM {
      negative_claim_basis: nonempty [Claim | Record]
      coverage: CoveragePosture
    }
  | BRIDGE_BASIS_UNRESOLVED {
      known_references: [Term] | NONE | OPEN
      unresolved_positions
      coverage: CoveragePosture
    }

EndpointActualityBinding {
  endpoint_reference_id
  exact_bearer_term
  existence_judgment_reference: OntologyExistenceJudgmentReference
  result: EndpointActualityResult
}

GoverningCriterionBinding :=
    SINGLE_GOVERNING_CRITERION {
      criterion_use: ContinuityCriterionUseBinding
    }
  | CLOSED_MAPPED_CRITERION_SET {
      criterion_uses:
          nonempty map<criterion_use_id, ContinuityCriterionUseBinding>
      criterion_mapping_references
    }
  | GOVERNING_CRITERION_NOT_APPLICABLE

ContinuityProfileReference {
  profile_id_and_version_or_reference_target
  profile_representation: Representation | NONE | OPEN
}

