  criterion_id_and_version_or_reference_target
  criterion_representation: Representation | NONE | OPEN
}

ContinuityRelationQualifierBinding {
  relation_kind
  qualifier_name
  attribute_term: Property
  requiredness: RelationQualifierRequiredness
}

ContinuitySnapshot := ContinuityDescription {
  as_of_boundary_or_bounded_interval
  snapshot_coverage
}

ContinuityGraphNodeReference {
  node_id: Identifier
  endpoint_or_term_reference: ContinuityEndpointReference | Term
}

