      existence:
          TARGET_EXISTS_AFTER_BOUNDARY
        | TARGET_DOES_NOT_EXIST_AFTER_BOUNDARY
        | POST_BOUNDARY_EXISTENCE_UNRESOLVED
    }
  | ACTIVITY_OR_PROCESS_POSTURE {
      occurrence_or_activity:
          TARGET_CONTINUES_AFTER_BOUNDARY
        | TARGET_CEASED_AT_BOUNDARY
        | POST_BOUNDARY_ACTIVITY_UNRESOLVED
    }
  | RELATION_STATE_STATUS_OR_ROLE_POSTURE {
      obtaining:
          TARGET_OBTAINS_AFTER_BOUNDARY
        | TARGET_DOES_NOT_OBTAIN_AFTER_BOUNDARY
        | POST_BOUNDARY_OBTAINING_UNRESOLVED
    }
  | RECORD_POSTURE {
